import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
const bytes=gunzipSync(Buffer.from('','base64'));
if(createHash('sha256').update(bytes).digest('hex')!=='6be226050fefe04dbddfcd1197e371bfbb0974adb5eb998cf4cf96e87ba84ce3')throw Error('RELEASE_HASH_MISMATCH');
for(const [name,code]of Object.entries(JSON.parse(bytes)))await Bun.write(new URL('./'+name,import.meta.url),code);
const app=await import(new URL('./expansion-entry.mjs',import.meta.url).href);
export default app.default;
